import React, { useRef, useEffect, useMemo } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid } from '@react-three/drei';
import * as THREE from 'three';
import './SurfaceViewer.css';

function SurfaceMesh({ points, isGroundTruth = false }) {
  const meshRef = useRef();

  const geometry = useMemo(() => {
    if (!points || points.length === 0) return null;

    const geo = new THREE.BufferGeometry();
    const positions = [];
    const colors = [];
    const indices = [];

    // Create vertices
    points.forEach(point => {
      positions.push(point[0], point[1], point[2]);

      if (isGroundTruth) {
        // Ground truth: green wireframe
        colors.push(0.2, 0.8, 0.3);
      } else {
        // Predicted: colored by force magnitude
        const forceMag = point[3] !== undefined
          ? Math.sqrt(point[3]**2 + point[4]**2 + point[5]**2)
          : 0;

        const hue = Math.max(0, Math.min(1, 1 - forceMag * 0.5)) * 0.6;
        const color = new THREE.Color().setHSL(hue, 0.8, 0.6);
        colors.push(color.r, color.g, color.b);
      }
    });

    // Create triangular mesh indices
    const gridSize = Math.sqrt(points.length);
    for (let y = 0; y < gridSize - 1; y++) {
      for (let x = 0; x < gridSize - 1; x++) {
        const a = y * gridSize + x;
        const b = y * gridSize + (x + 1);
        const c = (y + 1) * gridSize + x;
        const d = (y + 1) * gridSize + (x + 1);

        indices.push(a, b, c);
        indices.push(b, d, c);
      }
    }

    geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
    geo.setIndex(indices);
    geo.computeVertexNormals();

    return geo;
  }, [points, isGroundTruth]);

  useFrame(() => {
    if (meshRef.current && !isGroundTruth) {
      meshRef.current.rotation.y += 0.001;
    }
  });

  if (!geometry) return null;

  return (
    <mesh ref={meshRef} geometry={geometry}>
      {isGroundTruth ? (
        <meshBasicMaterial
          color="#20ff40"
          wireframe
          transparent
          opacity={0.3}
        />
      ) : (
        <meshStandardMaterial
          vertexColors
          metalness={0.3}
          roughness={0.7}
          side={THREE.DoubleSide}
        />
      )}
    </mesh>
  );
}

function ForceVectors({ points }) {
  const vectors = useMemo(() => {
    if (!points || points.length === 0) return [];

    return points.filter((_, i) => i % 8 === 0).map((point, idx) => {
      if (point[3] === undefined) return null;

      const origin = new THREE.Vector3(point[0], point[1], point[2]);
      const force = new THREE.Vector3(point[3], point[4], point[5]);
      const direction = force.clone().normalize();
      const length = Math.min(force.length() * 0.3, 0.5);
      const color = new THREE.Color().setHSL((1 - Math.min(force.length(), 1)) * 0.6, 1, 0.5);

      // Create ArrowHelper instance for React Three Fiber
      const arrow = new THREE.ArrowHelper(
        direction,
        origin,
        length,
        color.getHex(),
        length * 0.2,
        length * 0.1
      );

      return { key: idx, arrow };
    }).filter(Boolean);
  }, [points]);

  return (
    <group>
      {vectors.map(({ key, arrow }) => (
        <primitive key={key} object={arrow} />
      ))}
    </group>
  );
}

function Scene({ points, groundTruth, material }) {
  return (
    <>
      <color attach="background" args={['#0a0a0f']} />
      <ambientLight intensity={0.5} />
      <pointLight position={[10, 10, 10]} intensity={1} />
      <pointLight position={[-10, -10, -10]} intensity={0.5} color="#7b2ff7" />
      <spotLight position={[0, 10, 0]} angle={0.3} intensity={0.8} color="#00d4ff" />

      {groundTruth && groundTruth.length > 0 && (
        <SurfaceMesh points={groundTruth} isGroundTruth={true} />
      )}

      {points && points.length > 0 && (
        <>
          <SurfaceMesh points={points} isGroundTruth={false} />
          <ForceVectors points={points} />
        </>
      )}

      <Grid
        args={[10, 10]}
        cellSize={0.5}
        cellThickness={0.5}
        cellColor="#444444"
        sectionSize={2}
        sectionThickness={1}
        sectionColor="#666666"
        fadeDistance={30}
        fadeStrength={1}
        position={[0, -1.5, 0]}
      />

      <OrbitControls
        enableZoom={true}
        enablePan={true}
        enableRotate={true}
        maxDistance={10}
        minDistance={2}
      />
    </>
  );
}

function SurfaceViewer({ points, groundTruth, material }) {
  return (
    <div className="surface-viewer">
      <Canvas camera={{ position: [3, 3, 3], fov: 50 }}>
        <Scene points={points} groundTruth={groundTruth} material={material} />
      </Canvas>

      <div className="viewer-legend">
        <div className="legend-item">
          <div className="legend-color" style={{ background: 'linear-gradient(90deg, #ff4444, #ffaa00, #44ff44)' }}></div>
          <span>Force Heatmap (Red=High, Green=Low)</span>
        </div>
        <div className="legend-item">
          <div className="legend-color" style={{ background: '#20ff40', opacity: 0.3 }}></div>
          <span>Ground Truth Surface</span>
        </div>
      </div>
    </div>
  );
}

export default SurfaceViewer;
